#pragma once
// M2 multi-mode firmware — UDS DID/RID registries (Phase 9).
//
// Data-driven Data Identifier and Routine Identifier catalogs for UDS
// mode: names, ASCII-decodability, and security-gating flags. DID names
// and security requirements come from the OEM vehicle database
// (generated/json/dids.json, 'iso' make entries); generic SAE DIDs are
// compiled in as the default registry. Make-specific DID packs are
// generated by scripts/oem_extract.py into oem_gen.h (see udsreg.cpp).
//
// 0x27 stays a stub — the security flag only records that an ECU *may*
// require security access; no key algorithm exists anywhere here.
//
// Evidence: VERIFIED = compiles. INFERRED = untested against real ECUs.

#include <Arduino.h>
#include <stdint.h>

namespace udsreg {

// DID flags
constexpr uint8_t DID_ASCII = 0x01;  // payload decodes as ASCII text
constexpr uint8_t DID_SEC   = 0x02;  // ECU may gate this DID behind 0x27

struct DidEntry {
    uint16_t did;
    const char* name;
    uint8_t flags;
};

struct RidEntry {
    uint16_t rid;
    const char* name;
};

const DidEntry* findDid(uint16_t did);
const RidEntry* findRid(uint16_t rid);

// Decode a 0x22 positive-response payload (bytes AFTER the 62 did echo).
// ASCII-flagged DIDs print as text; others print hex. Returns false when
// the DID is unknown (caller prints raw hex).
bool decodeDid(uint16_t did, const uint8_t* d, uint8_t n,
               char* out, size_t cap);

// Registry introspection (console/mm).
uint16_t didCount();
const DidEntry* didAt(uint16_t i);
uint16_t ridCount();
const RidEntry* ridAt(uint16_t i);

} // namespace udsreg
